
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_mpwlyp1w_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_mpwlyp1w", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.392682259429718e+00, -4.310739556682942e+00, -4.195991877389662e+00, -4.037190817575294e+00, -3.821119806670250e+00, -3.534189021454718e+00, -3.166151772071852e+00, -2.716624766330121e+00, -2.203075851467945e+00, -1.661545221049849e+00, -1.123398821129319e+00, -7.463744152123776e-01, -6.400316452358457e-01, -5.351636319705655e-01, -3.925906717012329e-01, -2.506857314296825e-01, -1.416550969825559e-01, -5.087439072008745e-02, -1.598003387702122e-03, -4.309687995175128e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


